# ══════════════════════════════════════════════════════════════════
def _regions_like_trench(extra=None):
    out = []
    for r in TRENCH_REGIONS:
        d = {"slug": r["slug"], "name": r["name"], "cities": r["cities"], "area": r["area"]}
        d.update((extra or {}).get(r["slug"], {}))
        out.append(d)
    return out

